import type { BlogArticleFaq } from '../../../types/blog';

export const BODY: string = "\n<p>موقعك الإلكتروني سريع بقدر سرعة صوره. النص يحمل في أجزاء من الثانية، لكن صورة واحدة ثقيلة قد تؤخر الصفحة كاملة.</p>\n<p>صُمم <a href=\"/ar/tahsin-suwar-al-web/\">محسّن صور الويب</a> لهذه المشكلة. يضغط الصور لمواضع محددة في موقعك، مع إعدادات جاهزة لكل نوع صورة.</p>\n<p>يشرح هذا الدليل الإعدادات الجاهزة والخيارات وكيفية استخدام الأداة لتحسين موقعك كاملًا.</p>\n<h2 id=\"what-is-web-optimisation\">ما هو تحسين صور الويب؟</h2>\n<p>تحسين صور الويب يعني ضغط الصور وتغيير حجمها واختيار الصيغة الصحيحة لكل موضع في الصفحة. الهدف صفحة سريعة تبدو ممتازة.</p>\n<p>الصورة الرئيسية تحتاج إعدادات مختلفة عن الصورة المصغرة. التحسين الجيد يعامل كل موضع حسب احتياجه، لا بإعداد واحد للجميع.</p>\n<h2 id=\"presets-explained\">الإعدادات الجاهزة الخمسة لأداء الويب</h2>\n<p>الإعدادات الجاهزة الخمسة لأداء الويب هي: رئيسية، ومنتج، وبطاقة، ومصغرة، ومشاركة اجتماعية. كل إعداد يحدد الأبعاد والجودة والصيغة المناسبة لذلك الموضع.</p>\n<p>اختر الإعداد حسب مكان الصورة في صفحتك. الإعداد الصحيح يختصر التخمين ويعطي نتيجة متوازنة بين الجودة والسرعة.</p>\n<h2 id=\"hero-images\">كيف تحسّن الصور الرئيسية؟</h2>\n<p>لتحسين الصور الرئيسية، استخدم إعداد الصورة الرئيسية. يعطي أبعادًا كبيرة وجودة عالية، لأن الصورة الرئيسية أول ما يراه الزائر.</p>\n<p>لا تستخدم التحميل الكسول للصورة الرئيسية. يجب أن تحمل فورًا، لأن تأخيرها يعني صفحة تبدو فارغة في البداية.</p>\n<h2 id=\"product-images\">كيف تحسّن صور المنتجات؟</h2>\n<p>لتحسين صور المنتجات، استخدم إعداد المنتج. يعطي أبعادًا مربعة وجودة عالية، لأن المشتري يحتاج إلى رؤية تفاصيل المنتج بوضوح.</p>\n<p>قصّ صور المنتجات على المنتج نفسه قبل التحسين. القص المحكم يمنح المنتج حصة أكبر من الميزانية فيبدو أوضح.</p>\n<h2 id=\"cards-thumbnails\">البطاقات والصور المصغرة</h2>\n<p>البطاقات والصور المصغرة تظهر صغيرة، لذلك لا تحتاج إلى ملفات كبيرة. إعداد البطاقة يعطي أبعادًا صغيرة وجودة متوازنة.</p>\n<p>عشر بطاقات بوزن 50 كيلوبايت تحمل أسرع بكثير من عشر بطاقات بوزن 200 كيلوبايت. الفرق يظهر في سرعة الصفحة كاملة.</p>\n<h2 id=\"copy-img-button\">زر نسخ وسم الصورة</h2>\n<p>زر نسخ وسم الصورة يعطيك وسم HTML جاهزًا للصق في موقعك. الوسم يحمل الأبعاد الصحيحة والنص البديل وسمات التحميل الكسول.</p>\n<p>انسخ الوسم والصقه في صفحتك دون تعديل. هذه الميزة توفر الوقت وتمنع أخطاء كتابة الوسوم يدويًا.</p>\n<h2 id=\"lazy-loading\">التحميل الكسول الجيد</h2>\n<p>التحميل الكسول الجيد يعني تحميل الصور فقط عندما يقترب الزائر منها. الصور أسفل الصفحة لا تحمل حتى يمرر الزائر إليها.</p>\n<p>هذا يسرّع التحميل الأولي للصفحة بشكل كبير. لكن لا تستخدم التحميل الكسول للصورة الرئيسية، فهي يجب أن تظهر فورًا.</p>\n<h2 id=\"formats-web\">الصيغ للويب</h2>\n<p>الصيغ للويب: JPG للصور الفوتوغرافية، وWebP للأصغر حجمًا، وPNG للرسوم والنصوص. اختيار الصيغة الصحيحة يختصر حجم الملف دون فقدان الجودة.</p>\n<p>إذا قبلت منصتك WebP، فاستخدمه. إنه أصغر من JPG بجودة مماثلة، ويعمل في معظم المتصفحات الحديثة.</p>\n<h2 id=\"quality-slider\">منزلق الجودة: من 20 إلى 95 بالمئة</h2>\n<p>منزلق الجودة من 20 إلى 95 بالمئة يتيح لك التحكم الدقيق. جودة 80 مناسبة لمعظم صور الويب، و85 للصور الرئيسية.</p>\n<p>لا تستخدم جودة 95 إلا للصور التي تستحق ذلك. الفرق بين 85 و95 ضئيل، لكن حجم الملف يكبر بشكل ملحوظ.</p>\n<h2 id=\"exif-stripping\">إزالة بيانات EXIF ووزن الصفحة</h2>\n<p>إزالة بيانات EXIF تقلل وزن الصفحة. بيانات الكاميرا والموقع المرفقة بالصور تضيف كيلوبايتات دون فائدة للزائر.</p>\n<p>الأداة تزيل هذه البيانات تلقائيًا أثناء التحسين. الملف المنزّل نظيف وأصغر، ويحمي خصوصيتك أيضًا.</p>\n<h2 id=\"batch-web\">التحسين بالجملة لمواقع كاملة</h2>\n<p>التحسين بالجملة لمواقع كاملة يعني معالجة كل صور الموقع بإعدادات موحدة. ارفع الدفعة كاملة وحدد الإعداد لكل نوع صورة.</p>\n<p>لمواقع كبيرة، قسّم الصور حسب النوع: رئيسية ومنتج وبطاقة. كل مجموعة تحصل على إعدادها المناسب. وللأحجام المخصصة، استخدم <a href=\"/ar/daght-as-sura-ila-hajm-muayyan/\">ضاغط حجم الملف المستهدف</a>.</p>\n<h2 id=\"og-images\">المشاركة الاجتماعية وصور Open Graph</h2>\n<p>المشاركة الاجتماعية وصور Open Graph تحتاج أبعادًا محددة: 1200 في 630 بكسل لمعظم المنصات. الأداة تضبط هذه الأبعاد تلقائيًا.</p>\n<p>تتحول صور المشاركة إلى JPG لضمان التوافق. منصات التواصل تقص الصور وتعيد ضغطها، وJPG هو الصيغة الأكثر أمانًا هناك.</p>\n<h2 id=\"retina-web\">شاشات ريتينا عالية الكثافة</h2>\n<p>شاشات ريتينا عالية الكثافة تحتاج صورًا بأبعاد أكبر لتبدو حادة. صورة بأبعاد مضاعفة تبدو أوضح على هذه الشاشات.</p>\n<p>الحل ليس في زيادة حجم الملف، بل في الأبعاد. ارفع الأبعاد قليلًا واضغط بجودة متوازنة، وستبدو الصورة حادة على الشاشات الكثيفة.</p>\n<h2 id=\"alt-text-web\">النص البديل وإمكانية الوصول</h2>\n<p>النص البديل وإمكانية الوصول جزء من التحسين. اكتب نصًا بديلًا يصف الصورة فعلًا، حتى يفهمها من يستخدم قارئ شاشة.</p>\n<p>الأداة تحافظ على النص البديل الذي تكتبه في وسم HTML المنسوخ. لا تنسَ كتابته لكل صورة مهمة في موقعك.</p>\n<h2 id=\"cdn-caching\">شبكات CDN والتخزين المؤقت للصور</h2>\n<p>شبكات CDN والتخزين المؤقت للصور تسرّع موقعك أكثر. الصور المحسّنة تُحفظ في ذاكرة التخزين المؤقت، فلا تُنزّل مجددًا في كل زيارة.</p>\n<p>إذا استخدمت CDN، فارفع الصور المحسّنة إليه. الجمع بين التحسين وCDN يعطي أسرع نتيجة ممكنة.</p>\n<h2 id=\"webp-fallback\">WebP مع بديل JPG</h2>\n<p>WebP مع بديل JPG يعني تقديم WebP للمتصفحات الحديثة وJPG للقديمة. بهذا تحصل على أصغر حجم دون التضحية بالتوافق.</p>\n<p>استخدم وسم الصورة مع مصادر متعددة. المتصفح يختار الصيغة التي يدعمها تلقائيًا، والزائر لا يلاحظ أي فرق.</p>\n<h2 id=\"measuring-web\">كيف تقيس التحسن؟</h2>\n<p>قس التحسن بأدوات قياس السرعة المجانية قبل التحسين وبعده. لاحظ وقت تحميل الصفحة ومؤشرات الويب الأساسية.</p>\n<p>إذا تحسنت الأرقام وبدت الصور جيدة، فقد نجحت. وللخطوات العملية، اقرأ <a href=\"/ar/blog/kayfiyya-tahsin-as-suwar-li-surat-al-mawqi/\">كيفية تحسين الصور لسرعة الموقع</a> و<a href=\"/ar/blog/tahsin-as-suwar-li-core-web-vitals/\">تحسين الصور لمؤشرات الويب الأساسية</a>، أو جرّب <a href=\"/ar/daght-as-sura-ila-200kb/\">ضاغط 200 كيلوبايت</a> للصور الرئيسية.</p>\n";

export const FAQS: BlogArticleFaq[] = [{"question":"ما الإعداد الجاهز الذي أستخدمه لصورة رئيسية؟","answer":"لصورة رئيسية، استخدم إعداد الصورة الرئيسية. يعطي أبعادًا كبيرة وجودة عالية، ويحافظ على التفاصيل التي تظهر بملء الشاشة."},{"question":"لماذا تتحول الأداة إلى JPG لصور المشاركة الاجتماعية؟","answer":"لأن منصات التواصل تقص الصور وتعيد ضغطها، وJPG هو الصيغة الأكثر توافقًا معها. الأداة تختار JPG لصور المشاركة لضمان ظهورها بشكل صحيح في كل مكان."},{"question":"هل أبقي التحميل الكسول مفعّلًا في صورتي الرئيسية؟","answer":"لا، اترك التحميل الكسول مفعّلًا لكل الصور ما عدا الصورة الرئيسية. الصورة الرئيسية يجب أن تحمل فورًا لأنها أول ما يراه الزائر."},{"question":"ماذا يفعل خيار التقليل فقط؟","answer":"خيار التقليل فقط يصغّر الصور الكبيرة إلى الأبعاد المطلوبة دون ضغط إضافي. مفيد عندما تكون صورك بجودة جيدة أصلًا وتحتاج فقط إلى تصغير الأبعاد."},{"question":"لماذا تُسمى الملفات المنزّلة بلاحقة -web؟","answer":"اللاحقة -web تميّز النسخ المحسّنة عن الأصول. بهذا تعرف أي ملف هو النسخة الجاهزة للويب وأي ملف هو الأصل، دون فتحهما."},{"question":"هل يمكنني استخدام محسّن صور الويب بدل ضاغط الصور بالجملة؟","answer":"نعم، لمعظم الحالات. محسّن الويب يضغط الصور بإعدادات مخصصة لكل موضع في الصفحة، بينما ضاغط الجملة يستخدم هدفًا واحدًا للجميع. اختر حسب احتياجك."}];
